#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;
int main(){
    ios::sync_with_stdio(false);cin.tie(nullptr);
    int n;long long minutes;if(!(cin>>n>>minutes))return 0;
    string direction;cin>>direction;
    vector<long long> capacity(n);long long answer=0;
    for(auto &x:capacity){cin>>x;answer+=x;}
    int start=0;
    while(start<n&&direction[start]==direction[(start+n-1)%n])++start;
    if(start==n){cout<<answer<<'\n';return 0;}
    int used=0;
    while(used<n){
        int index=(start+used)%n;
        char current=direction[index];
        long long first=capacity[index],last=first,total=0;
        while(used<n&&direction[(start+used)%n]==current){
            last=capacity[(start+used)%n];total+=last;++used;
        }
        long long sink=current=='R'?last:first;
        answer-=min(minutes,total-sink);
    }
    cout<<answer<<'\n';
}
