    ios::sync_with_stdio(false);cin.tie(nullptr);
    int n,queries;if(!(cin>>n>>queries))return 0;
    vector<long long> deadline(n);
    for(auto &value:deadline)cin>>value;
    for(auto &value:deadline){long long travel;cin>>travel;value-=travel;}
    sort(deadline.rbegin(),deadline.rend());
    while(queries--){
        int required;long long wake;cin>>required>>wake;
        cout<<(deadline[required-1]>wake?"YES":"NO")<<'\n';
    }
}
